-- Additive migration; preserve all retained grade-seven business data.
ALTER TABLE kb_outline
 ADD COLUMN catalog_kind VARCHAR(30) NOT NULL DEFAULT 'MATERIAL_COVERAGE',
 ADD COLUMN subject VARCHAR(30) NULL,
 ADD COLUMN textbook_version VARCHAR(40) NULL,
 ADD COLUMN grade VARCHAR(20) NULL,
 ADD COLUMN term VARCHAR(20) NULL,
 ADD COLUMN edition VARCHAR(100) NULL,
 ADD COLUMN catalog_source VARCHAR(1000) NULL,
 ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
 ADD KEY idx_kb_outline_textbook(subject,textbook_version,grade,term,status);

UPDATE sys_dict_data SET status='1',update_by='admin',update_time=NOW() WHERE dict_type='kb_subject' AND dict_value NOT IN ('MATH','SCIENCE');

